class Point {
  public:
    Point();  // Compiler-synthesized default constructor if not provided
    virtual ~Point();  // Virtual destructor for polymorphic deletion
    // Other members...
};

class Point3d : public Point {
  public:
    Point3d();  // May invoke base constructor
    ~Point3d() override;  // Overridden virtual destructor
    // Implementation notes: The compiler ensures that when deleting an array of Point3d,
    // it calls Point3d::~Point3d() for each element, which in turn calls Point::~Point().
    // The vptr is adjusted during construction to point to Point3d's vtable.
};

code_example:
#include <iostream>

class Point {
public:
    Point() { std::cout << "Point constructor" << std::endl; }
    virtual ~Point() { std::cout << "Point destructor" << std::endl; }
};

class Point3d : public Point {
public:
    Point3d() { std::cout << "Point3d constructor" << std::endl; }
    ~Point3d() override { std::cout << "Point3d destructor" << std::endl; }
};

int main() {
    Point* array = new Point3d[3];  // Allocates array of 3 Point3d objects
    // Compiler synthesizes code for array construction, invoking constructors in order
    delete[] array;  // Invokes vec_delete()-like mechanism: loops through array,
                     // calls destructors via vptr, then deallocates memory
    return 0;
}
